        [TestCase("def inner():\n    try:\n        yield 1\n    except ValueError as e:\n        print('inner caught', e)\n        yield 100\n    yield 2\n    return 'r'\ndef outer():\n    r = yield from inner()\n    print('outer got', r)\n    yield 3\ng = outer()\nprint(next(g))\nprint(g.throw(ValueError, 'boom'))\nprint(next(g))\nprint(next(g))\ntry:\n    next(g)\nexcept StopIteration:\n    print('done')", "1\ninner caught boom\n100\n2\nouter got r\n3\ndone", TestName = "yf_throw_caught_by_inner")]
