        [TestCase("def inner():\n    try:\n        yield 1\n    except ValueError:\n        return 'handled'\ndef outer():\n    r = yield from inner()\n    print('inner returned', r)\n    yield 'after'\n    return 'outer done'\ng = outer()\nnext(g)\nprint(g.throw(ValueError))\ntry:\n    next(g)\nexcept StopIteration as e:\n    print('stop', e.value)", "inner returned handled\nafter\nstop outer done", TestName = "yf_throw_inner_returns")]
        [TestCase("def inner():\n    try:\n        yield 1\n    finally:\n        print('inner finally')\ndef outer():\n    try:\n        yield from inner()\n    finally:\n        print('outer finally')\ng = outer()\nnext(g)\nprint(g.close())\ntry:\n    next(g)\nexcept StopIteration:\n    print('closed')", "inner finally\nouter finally\nNone\nclosed", TestName = "yf_close_runs_inner_then_outer_finally")]
        [TestCase("def inner():\n    try:\n        yield 1\n    except GeneratorExit:\n        print('inner exit')\n        return 'x'\ndef outer():\n    try:\n        r = yield from inner()\n        print('not reached', r)\n        yield 2\n    finally:\n        print('outer finally')\ng = outer()\nnext(g)\ng.close()\nprint('closed')\ntry:\n    next(g)\nexcept StopIteration:\n    print('done')", "inner exit\nouter finally\nclosed\ndone", TestName = "yf_close_inner_swallows")]
