        [TestCase("def outer():\n    try:\n        yield from [1, 2, 3]\n    except ValueError as e:\n        print('outer caught', e)\n        yield 'x'\ng = outer()\nprint(next(g))\nprint(g.throw(ValueError('v')))\ng = outer()\nnext(g)\ng.close()\nprint('closed')\ndef outer2():\n    try:\n        yield from iter([1, 2])\n    finally:\n        print('fin')\ng = outer2()\nnext(g)\ntry:\n    g.throw(ZeroDivisionError('k'))\nexcept ZeroDivisionError as e:\n    print('escaped', e)", "1\nouter caught v\nx\nclosed\nfin\nescaped k", TestName = "yf_plain_iterator_delegate")]
        [TestCase("def a():\n    try:\n        yield 'a1'\n    except ValueError:\n        print('a caught')\n        yield 'a2'\n    finally:\n        print('a finally')\ndef b():\n    try:\n        yield from a()\n    finally:\n        print('b finally')\ndef c():\n    try:\n        yield from b()\n    finally:\n        print('c finally')\ng = c()\nprint(next(g))\nprint(g.throw(ValueError))\ng.close()\nprint('closed')\nh = c()\nnext(h)\nh.close()\nprint('closed 2')\nk = c()\nnext(k)\ntry:\n    k.throw(ZeroDivisionError('q'))\nexcept ZeroDivisionError as e:\n    print('escaped', e)", "a1\na caught\na2\na finally\nb finally\nc finally\nclosed\na finally\nb finally\nc finally\nclosed 2\na finally\nb finally\nc finally\nescaped q", TestName = "yf_chain_three_levels")]
        [TestCase("def inner():\n    got = []\n    while len(got) < 3:\n        try:\n            got.append((yield len(got)))\n        except ValueError:\n            got.append('V')\n    return got\ndef outer():\n    r = yield from inner()\n    print('result', r)\ng = outer()\nprint(next(g))\nprint(g.send('a'))\nprint(g.throw(ValueError))\ntry:\n    g.send('c')\nexcept StopIteration:\n    print('done')", "0\n1\n2\nresult ['a', 'V', 'c']\ndone", TestName = "yf_throw_then_send")]
